#!/usr/bin/env python3
import json,sys
from pathlib import Path
s=json.loads("\"diff --git a/skills/codex-delegate/scripts/relay.mjs b/skills/codex-delegate/scripts/relay.mjs\\nindex 70372f8..ff87a02 100644\\n--- a/skills/codex-delegate/scripts/relay.mjs\\n+++ b/skills/codex-delegate/scripts/relay.mjs\\n@@ -164,12 +164,7 @@ function timestamp() {\\n function buildArgv(opts, finalPath) {\\n   const argv = [\\\"exec\\\"];\\n   if (opts.resumeLast) argv.push(\\\"resume\\\", \\\"--last\\\");\\n-  // ponytail: shell:true on win32 (needed for the codex.cmd shim) doesn't quote\\n-  // args, so a temp path with spaces (C:\\\\Users\\\\First Last\\\\...) splits and the\\n-  // trailing \\\"-\\\" misparses (issue #3). Quote the only spaceable arg in argv.\\n-  // Ceiling: if quoting proves too blunt, drop shell:true and resolve the shim.\\n-  const outPath = process.platform === \\\"win32\\\" ? `\\\"${finalPath}\\\"` : finalPath;\\n-  argv.push(\\\"--json\\\", \\\"-o\\\", outPath);\\n+  argv.push(\\\"--json\\\", \\\"-o\\\", finalPath);\\n   // `-s`/`-C` are not accepted by `exec resume`; resume inherits the original\\n   // session's sandbox and working root, and we set the child process cwd below.\\n   if (!opts.resumeLast) {\\n@@ -251,12 +246,28 @@ function reportUnavailable(writeResult, resultPath) {\\n   process.exit(127);\\n }\\n \\n+// On Windows, npm's codex.cmd needs cmd.exe. Serialize argv as a command\\n+// line rather than handing an unquoted array to spawn({ shell: true }).\\n+function quoteForCmd(arg) {\\n+  const value = String(arg);\\n+  if (value === \\\"\\\") return '\\\"\\\"';\\n+  if (!/[\\\\s&()^|<>\\\"]/u.test(value)) return value;\\n+  return `\\\"${value.replace(/\\\"/g, '\\\"\\\"')}\\\"`;\\n+}\\n+\\n+function spawnCodex(argv, opts) {\\n+  const spawnOpts = { cwd: opts.cd, stdio: [\\\"pipe\\\", \\\"pipe\\\", \\\"pipe\\\"] };\\n+  if (process.platform !== \\\"win32\\\") return spawn(\\\"codex\\\", argv, spawnOpts);\\n+  const commandLine = [\\\"codex\\\", ...argv].map(quoteForCmd).join(\\\" \\\");\\n+  return spawn(\\\"cmd.exe\\\", [\\\"/d\\\", \\\"/s\\\", \\\"/c\\\", commandLine], {\\n+    ...spawnOpts,\\n+    windowsHide: true,\\n+  });\\n+}\\n+\\n function dispatchToCodex(opts, brief, run, writeResult) {\\n   const argv = buildArgv(opts, run.finalPath);\\n-  // shell:true on Windows so the codex.cmd shim resolves (see codexVersion). Safe:\\n-  // the brief is fed via child.stdin below — never argv — and argv holds only\\n-  // sandbox enums, model names, and file paths, with no shell metacharacters.\\n-  const child = spawn(\\\"codex\\\", argv, { cwd: opts.cd, stdio: [\\\"pipe\\\", \\\"pipe\\\", \\\"pipe\\\"], shell: process.platform === \\\"win32\\\" });\\n+  const child = spawnCodex(argv, opts);\\n \\n   let threadId = null;\\n   let stdoutBuf = \\\"\\\";\\ndiff --git a/tests/codex-relay.test.mjs b/tests/codex-relay.test.mjs\\nnew file mode 100644\\nindex 0000000..3381c49\\n--- /dev/null\\n+++ b/tests/codex-relay.test.mjs\\n@@ -0,0 +1,98 @@\\n+import { test } from 'node:test';\\n+import assert from 'node:assert/strict';\\n+import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, readdirSync, existsSync } from 'node:fs';\\n+import { tmpdir } from 'node:os';\\n+import { join, resolve } from 'node:path';\\n+import { spawnSync } from 'node:child_process';\\n+import { fileURLToPath } from 'node:url';\\n+\\n+const relay = resolve(fileURLToPath(new URL('../skills/codex-delegate/scripts/relay.mjs', import.meta.url)));\\n+\\n+function fixture() {\\n+  const root = mkdtempSync(join(tmpdir(), 'relay path with spaces '));\\n+  const bin = join(root, 'bin');\\n+  const repo = join(root, 'repo');\\n+  mkdirSync(bin);\\n+  mkdirSync(repo);\\n+  assert.equal(spawnSync('git', ['init', '-q'], { cwd: repo }).status, 0);\\n+  const brief = join(root, 'brief.txt');\\n+  writeFileSync(brief, 'PING_FROM_CODEX\\\\n');\\n+  const codex = join(bin, 'codex');\\n+  writeFileSync(codex, `#!/usr/bin/env node\\n+const fs = require('node:fs');\\n+const argv = process.argv.slice(2);\\n+if (argv[0] === '--version') { console.log('codex-test'); process.exit(0); }\\n+const idx = argv.indexOf('-o');\\n+if (idx < 0 || argv.at(-1) !== '-' || argv[idx + 1]?.includes('\\\"')) process.exit(2);\\n+let brief = '';\\n+process.stdin.on('data', c => brief += c);\\n+process.stdin.on('end', () => {\\n+ fs.writeFileSync(argv[idx + 1], brief.trim());\\n+ console.log(JSON.stringify({thread_id:'test-thread'}));\\n+});\\n+`);\\n+  const chmod = spawnSync('chmod', ['+x', codex]);\\n+  assert.equal(chmod.status, 0);\\n+  return { root, bin, repo, brief };\\n+}\\n+\\n+function checkResult(run, outDir) {\\n+  assert.equal(run.status, 0, `stdout: ${run.stdout}\\\\nstderr: ${run.stderr}`);\\n+  const result = JSON.parse(readFileSync(join(outDir, 'result.json'), 'utf8'));\\n+  assert.equal(result.status, 'completed');\\n+  assert.equal(result.finalMessage, 'PING_FROM_CODEX');\\n+  assert.deepEqual(result.touchedFiles, []);\\n+  assert.equal(result.threadId, 'test-thread');\\n+  assert.equal(readFileSync(result.eventsPath, 'utf8').trim(), '{\\\"thread_id\\\":\\\"test-thread\\\"}');\\n+  assert.equal(readFileSync(result.finalPath, 'utf8'), 'PING_FROM_CODEX');\\n+}\\n+\\n+test('POSIX relay preserves spaced output path and stdin', { skip: process.platform === 'win32' }, () => {\\n+  const f = fixture();\\n+  const outDir = join(f.root, 'out path');\\n+  const run = spawnSync(process.execPath, [relay, '--brief', f.brief, '--cd', f.repo, '--read-only', '--out-dir', outDir], {\\n+    env: { ...process.env, PATH: `${f.bin}:${process.env.PATH}` }, encoding: 'utf8',\\n+  });\\n+  checkResult(run, outDir);\\n+});\\n+\\n+test('POSIX default temp output with spaces', { skip: process.platform === 'win32' }, () => {\\n+  const f = fixture();\\n+  const run = spawnSync(process.execPath, [relay, '--brief', f.brief, '--cd', f.repo, '--read-only'], {\\n+    env: { ...process.env, TMPDIR: f.root, PATH: `${f.bin}:${process.env.PATH}` }, encoding: 'utf8',\\n+  });\\n+  const runRoot = join(f.root, 'delegate-relay');\\n+  assert.ok(existsSync(runRoot), `default output directory missing: ${run.stderr}`);\\n+  checkResult(run, join(runRoot, readdirSync(runRoot)[0]));\\n+});\\n+\\n+test('Windows launch branch serializes spaced arguments (POSIX cmd shim simulation)', { skip: process.platform === 'win32' }, () => {\\n+  const f = fixture();\\n+  const outDir = join(f.root, 'Windows profile space', 'out path');\\n+  const preload = join(f.root, 'win32.cjs');\\n+  writeFileSync(preload, `Object.defineProperty(process, 'platform', {value: 'win32'});\\\\n`);\\n+  // Mock cmd.exe records the /d /s /c command string and checks quoting.\\n+  // Native cmd.exe parsing is not exercised by this simulation.\\n+  const cmd = join(f.bin, 'cmd.exe');\\n+  writeFileSync(cmd, `#!/usr/bin/env node\\n+const fs = require('node:fs');\\n+const argv = process.argv.slice(2);\\n+if (argv.join(' ').includes('--version')) { console.log('codex-test'); process.exit(0); }\\n+if (argv.slice(0,3).join(' ') !== '/d /s /c') process.exit(3);\\n+const line = argv[3];\\n+if (!line.includes('\\\"${outDir}/final.txt\\\"')) process.exit(4);\\n+const output = line.match(/-o \\\"([^\\\"]+)\\\"/);\\n+if (!output || !line.endsWith(' -')) process.exit(5);\\n+let input='';\\n+process.stdin.on('data', c => input += c);\\n+process.stdin.on('end', () => {\\n+ fs.writeFileSync(output[1], input.trim());\\n+ console.log(JSON.stringify({thread_id:'test-thread'}));\\n+});\\n+`);\\n+  assert.equal(spawnSync('chmod', ['+x', cmd]).status, 0);\\n+  const run = spawnSync(process.execPath, ['--require', preload, relay, '--brief', f.brief, '--cd', f.repo, '--read-only', '--out-dir', outDir], {\\n+    env: { ...process.env, PATH: `${f.bin}:${process.env.PATH}` }, encoding: 'utf8',\\n+  });\\n+  checkResult(run, outDir);\\n+});\\n\"")
p=Path(sys.argv[1]); p.parent.mkdir(parents=True,exist_ok=True)
with p.open('ab') as f: f.write(s.encode('utf-8'))
